using MediatR;using Microsoft.AspNetCore.Mvc;using WhatsBiz.Api.Authorization;using WhatsBiz.Application.Features.Administration;using WhatsBiz.SharedKernel;namespace WhatsBiz.Api.Controllers;[ApiController,Route("api/admin")]public sealed class AdminController(ISender sender):ControllerBase{private string?CurrentUser=>User.Identity?.Name;[HttpGet("company"),HasPermission(Permissions.Admin.View)]public Task<CompanyDto>Company(CancellationToken t)=>sender.Send(new GetCompany(),t);[HttpPut("company"),HasPermission(Permissions.Admin.Company)]public Task<CompanyDto>Company(CompanyInput x,CancellationToken t)=>sender.Send(new UpdateCompany(x),t);[HttpGet("branches"),HasPermission(Permissions.Admin.View)]public Task<IReadOnlyCollection<BranchDto>>Branches(CancellationToken t)=>sender.Send(new GetBranches(),t);[HttpPost("branches"),HasPermission(Permissions.Admin.Settings)]public Task<BranchDto>Branch(BranchInput x,CancellationToken t)=>sender.Send(new CreateBranch(x),t);[HttpGet("settings"),HasPermission(Permissions.Admin.View)]public Task<IReadOnlyCollection<SettingDto>>Settings(CancellationToken t)=>sender.Send(new GetSettings(),t);[HttpPut("settings"),HasPermission(Permissions.Admin.Settings)]public async Task<IActionResult>Settings(IReadOnlyCollection<SettingInput>x,CancellationToken t){await sender.Send(new UpdateSettings(x,CurrentUser),t);return NoContent();}[HttpGet("financial-years"),HasPermission(Permissions.Admin.View)]public Task<IReadOnlyCollection<FinancialYearDto>>FinancialYears(CancellationToken t)=>sender.Send(new GetFinancialYears(),t);[HttpPost("financial-years"),HasPermission(Permissions.Admin.Settings)]public async Task<IActionResult>FinancialYear(FinancialYearInput x,CancellationToken t){await sender.Send(new SaveFinancialYear(x),t);return NoContent();}[HttpGet("backup"),HasPermission(Permissions.Admin.Backup)]public Task<IReadOnlyCollection<BackupDto>>Backups(CancellationToken t)=>sender.Send(new GetBackups(),t);[HttpPost("backup"),HasPermission(Permissions.Admin.Backup)]public Task<BackupDto>Backup(CancellationToken t)=>sender.Send(new CreateBackup(CurrentUser),t);[HttpPost("restore"),HasPermission(Permissions.Admin.Restore)]public Task<RestoreResultDto>Restore(RestoreInput x,CancellationToken t)=>sender.Send(new RestoreDatabase(x,CurrentUser),t);[HttpGet("audit"),HasPermission(Permissions.Admin.Audit)]public Task<IReadOnlyCollection<AuditDto>>Audit(DateTimeOffset?from,DateTimeOffset?to,string?action,int take=200,CancellationToken t=default)=>sender.Send(new GetAudit(from,to,action,take),t);[HttpGet("login-history"),HasPermission(Permissions.Admin.Audit)]public Task<IReadOnlyCollection<LoginDto>>Logins(DateTimeOffset?from,DateTimeOffset?to,int take=200,CancellationToken t=default)=>sender.Send(new GetLoginHistory(from,to,take),t);}
